"""Frozen Wave6 cost inputs and estimates; independent of later ORM changes."""
# ruff: noqa: E501

TABLES = ('cost_source_captures', 'cost_input_snapshots', 'cost_current_inputs', 'cost_estimates')

SCHEMA_SQL = (
    "\nCREATE TABLE cost_source_captures (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcapture_key VARCHAR(160) NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tinput_id UUID NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\tproposed_inputs JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tUNIQUE (tenant_id, product_id, owner_id, capture_key), \n\tUNIQUE (tenant_id, product_id, input_id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id, input_id), \n\tCHECK (revision = 1 AND status = 'unapplied' AND expires_at > created_at)\n)\n\n",
    'CREATE INDEX ix_cost_source_captures_tenant_id ON cost_source_captures (tenant_id)',
    "\nCREATE TABLE cost_input_snapshots (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcapture_id UUID NOT NULL, \n\tprevious_input_id UUID, \n\tprevious_revision INTEGER, \n\tinputs JSONB NOT NULL, \n\tinputs_sha256 VARCHAR(64) NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\tcomparison JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tUNIQUE (tenant_id, product_id, build_id, revision), \n\tUNIQUE (tenant_id, product_id, build_id, id, revision), \n\tUNIQUE (tenant_id, product_id, capture_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, capture_id, id) REFERENCES cost_source_captures (tenant_id, product_id, project_id, build_id, id, input_id), \n\tFOREIGN KEY(tenant_id, product_id, build_id, previous_input_id, previous_revision) REFERENCES cost_input_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (status = 'recorded' AND revision > 0), \n\tCHECK ((previous_input_id IS NULL AND previous_revision IS NULL AND revision = 1) OR (previous_input_id IS NOT NULL AND previous_revision IS NOT NULL AND previous_input_id <> id AND revision = previous_revision + 1))\n)\n\n",
    'CREATE INDEX ix_cost_input_snapshots_tenant_id ON cost_input_snapshots (tenant_id)',
    '\nCREATE TABLE cost_current_inputs (\n\tproduct_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tinput_id UUID NOT NULL, \n\tinput_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, build_id), \n\tFOREIGN KEY(tenant_id, product_id, build_id, input_id, input_revision) REFERENCES cost_input_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (input_revision > 0)\n)\n\n',
    'CREATE INDEX ix_cost_current_inputs_tenant_id ON cost_current_inputs (tenant_id)',
    "\nCREATE TABLE cost_estimates (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcost_input_id UUID NOT NULL, \n\tcost_input_revision INTEGER NOT NULL, \n\tas_of TIMESTAMP WITH TIME ZONE NOT NULL, \n\tprojection JSONB NOT NULL, \n\tprojection_sha256 VARCHAR(64) NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tFOREIGN KEY(tenant_id, product_id, build_id, cost_input_id, cost_input_revision) REFERENCES cost_input_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (revision = 1 AND status = 'estimated' AND cost_input_revision > 0), \n\tCHECK (as_of <= created_at)\n)\n\n",
    'CREATE INDEX ix_cost_estimates_tenant_id ON cost_estimates (tenant_id)',
)
